# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">HAC VE KURBAN İBADETİNİN KÜLTÜRÜMÜZE YANSIMALARI (DKAB.7.2.3)</text>\n  <rect x="25" y="48" width="210" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="130" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1d4ed8">1. Tarihî ve Mimari Miras</text>\n  <text x="40" y="98" font-size="11" fill="#334155">• Surre Alayları: Osmanlı\'da</text>\n  <text x="40" y="116" font-size="11" fill="#334155">  Mekke ve Medine\'ye (Haremeyn)</text>\n  <text x="40" y="134" font-size="11" fill="#334155">  gönderilen hediye kervanları</text>\n  <text x="40" y="158" font-size="11" fill="#334155">• Haremeyn Vakıfları ve</text>\n  <text x="40" y="176" font-size="11" fill="#334155">  Hicaz Demir Yolu</text>\n  <text x="40" y="200" font-size="11" fill="#334155">• Kâbe tasvirli çiniler, Sakal-ı</text>\n  <text x="40" y="218" font-size="11" fill="#334155">  Şerif ve Hırka-i Saadet ziyareti</text>\n  <rect x="245" y="48" width="210" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="350" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">2. Hac Geleneklerimiz</text>\n  <text x="260" y="98" font-size="11" fill="#334155">• Hac Uğurlama: Dualar, ilahiler,</text>\n  <text x="260" y="116" font-size="11" fill="#334155">  helalleşme ve kurban kesimi</text>\n  <text x="260" y="140" font-size="11" fill="#334155">• Hac Karşılama ve Ziyaret:</text>\n  <text x="260" y="158" font-size="11" fill="#334155">  Hacılara zemzem ve hurma</text>\n  <text x="260" y="176" font-size="11" fill="#334155">  ikram edilmesi, hediyeleşme</text>\n  <text x="260" y="200" font-size="11" fill="#334155">• "Allah kabul etsin, bize de</text>\n  <text x="260" y="218" font-size="11" fill="#334155">  nasip etsin" hayır duaları</text>\n  <rect x="465" y="48" width="210" height="190" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="570" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#a16207">3. Kurban ve Edebiyatımız</text>\n  <text x="480" y="98" font-size="11" fill="#334155">• Kurban Bayramı: Akraba ve</text>\n  <text x="480" y="116" font-size="11" fill="#334155">  komşu ziyareti, küslerin barışması</text>\n  <text x="480" y="140" font-size="11" fill="#334155">• Kızılay ve TDV aracılığıyla</text>\n  <text x="480" y="158" font-size="11" fill="#334155">  mazlum coğrafyalara vekâlet</text>\n  <text x="480" y="182" font-size="11" fill="#334155">• "Kurban olayım", "Hacivat",</text>\n  <text x="480" y="200" font-size="11" fill="#334155">  Yunus Emre ve Fuzûlî şiirleri</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">EN\'ÂM SURESİ 162. AYET: TEVHİT, İHLAS VE TESLİMİYET (DKAB.7.2.4)</text>\n  <rect x="28" y="46" width="644" height="76" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="350" y="72" text-anchor="middle" font-size="15" font-weight="bold" fill="#92400e">قُلْ إِنَّ صَلَاتِي وَنُسُكِي وَمَحْيَايَ وَمَمَاتِي لِلّٰهِ رَبِّ الْعَالَمِينَ</text>\n  <text x="350" y="96" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#78350f">"De ki: Şüphesiz benim namazım, ibadetlerim (kurbanım/haccım), hayatım ve ölümüm</text>\n  <text x="350" y="113" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#78350f">âlemlerin Rabbi olan Allah içindir." (En\'âm suresi, 162. ayet)</text>\n  <rect x="28" y="134" width="152" height="106" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="104" y="156" text-anchor="middle" font-size="12" font-weight="bold" fill="#1d4ed8">صَلَاتِي (Salâtî)</text>\n  <text x="104" y="178" text-anchor="middle" font-size="11" fill="#334155">Benim namazım</text>\n  <text x="104" y="198" text-anchor="middle" font-size="10.5" fill="#475569">ve duam; kulun</text>\n  <text x="104" y="214" text-anchor="middle" font-size="10.5" fill="#475569">Rabbine yönelişi</text>\n  <rect x="192" y="134" width="152" height="106" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="268" y="156" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">نُسُكِي (Nüsükî)</text>\n  <text x="268" y="178" text-anchor="middle" font-size="11" fill="#334155">Kurbanım, haccım</text>\n  <text x="268" y="198" text-anchor="middle" font-size="10.5" fill="#475569">ve tüm ibadetlerim</text>\n  <text x="268" y="214" text-anchor="middle" font-size="10.5" fill="#475569">(menâsik/kulluk)</text>\n  <rect x="356" y="134" width="152" height="106" rx="8" fill="#fdf2f8" stroke="#ec4899"/>\n  <text x="432" y="156" text-anchor="middle" font-size="12" font-weight="bold" fill="#be185d">مَحْيَايَ وَمَمَاتِي</text>\n  <text x="432" y="178" text-anchor="middle" font-size="11" fill="#334155">Hayatım ve ölümüm;</text>\n  <text x="432" y="198" text-anchor="middle" font-size="10.5" fill="#475569">ömür boyu yapılan</text>\n  <text x="432" y="214" text-anchor="middle" font-size="10.5" fill="#475569">güzel davranışlar</text>\n  <rect x="520" y="134" width="152" height="106" rx="8" fill="#f3e8ff" stroke="#a855f7"/>\n  <text x="596" y="156" text-anchor="middle" font-size="12" font-weight="bold" fill="#7e22ce">لِلّٰهِ رَبِّ الْعَالَمِينَ</text>\n  <text x="596" y="178" text-anchor="middle" font-size="11" fill="#334155">Âlemlerin Rabbi</text>\n  <text x="596" y="198" text-anchor="middle" font-size="10.5" fill="#475569">Allah içindir</text>\n  <text x="596" y="214" text-anchor="middle" font-size="10.5" fill="#475569">(Tevhit ve İhlas)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">HAC, UMRE VE KURBAN TEMASI BÜTÜNCÜL ÖZET TABLOSU</text>\n  <rect x="25" y="48" width="210" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="130" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1d4ed8">Hac İbadeti (Farz)</text>\n  <text x="40" y="98" font-size="11" fill="#334155">• Zaman: Zilhicce (Arefe + Bayram)</text>\n  <text x="40" y="120" font-size="11" fill="#334155">• 3 Farzı: İhram, Arafat Vakfesi,</text>\n  <text x="40" y="138" font-size="11" fill="#334155">  Ziyaret Tavafı</text>\n  <text x="40" y="162" font-size="11" fill="#334155">• Vacipleri: Müzdelife vakfesi,</text>\n  <text x="40" y="180" font-size="11" fill="#334155">  Sa\'y (Safa-Merve), Şeytan</text>\n  <text x="40" y="198" font-size="11" fill="#334155">  taşlama, Veda tavafı, tıraş</text>\n  <rect x="245" y="48" width="210" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="350" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">Umre İbadeti (Sünnet)</text>\n  <text x="260" y="98" font-size="11" fill="#334155">• Zaman: Kurban Bayramı günleri</text>\n  <text x="260" y="116" font-size="11" fill="#334155">  dışında yılın her zamanı</text>\n  <text x="260" y="140" font-size="11" fill="#334155">• Unsurları: İhram, Tavaf, Sa\'y</text>\n  <text x="260" y="158" font-size="11" fill="#334155">  ve tıraş olup ihramdan çıkma</text>\n  <text x="260" y="182" font-size="11" fill="#334155">• Vakfe, şeytan taşlama ve</text>\n  <text x="260" y="200" font-size="11" fill="#334155">  kurban kesme umrede yoktur</text>\n  <rect x="465" y="48" width="210" height="190" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="570" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#a16207">Kurban İbadeti (Vacip)</text>\n  <text x="480" y="98" font-size="11" fill="#334155">• Zaman: Kurban Bayramı\'nın</text>\n  <text x="480" y="116" font-size="11" fill="#334155">  ilk 3 günü (Zilhicce 10-12)</text>\n  <text x="480" y="140" font-size="11" fill="#334155">• Hayvanlar: Koyun/keçi (1 yaş,</text>\n  <text x="480" y="158" font-size="11" fill="#334155">  1 kişi); sığır/manda (2 yaş, 1-7</text>\n  <text x="480" y="176" font-size="11" fill="#334155">  kişi); deve (5 yaş, 1-7 kişi)</text>\n  <text x="480" y="200" font-size="11" fill="#334155">• Paylaşım: Üçte bir aile, misafir</text>\n  <text x="480" y="218" font-size="11" fill="#334155">  ve yoksullar (Hz. İbrahim sünneti)</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
